// Convierte la respuesta REST de Supabase en un item por seguimiento.
const output = [];

for (const item of $input.all()) {
  const value = item.json;
  const rows = Array.isArray(value)
    ? value
    : Array.isArray(value?.body)
      ? value.body
      : value?.id
        ? [value]
        : [];

  for (const row of rows) {
    if (row?.id && row?.reminder_at) {
      output.push({ json: row });
    }
  }
}

return output;

// GREEN CHIMP CRM | PREPARAR CORREO DE SEGUIMIENTO MANUAL
// La fecha proviene exclusivamente de crm_leads.reminder_at,
// capturada por el usuario en la página del CRM.

const row = $json || {};
const raw = row.raw_payload && typeof row.raw_payload === 'object'
  ? row.raw_payload
  : {};

function text(value, fallback = '') {
  const result = String(value ?? '').trim();
  return result || fallback;
}

function escapeHtml(value) {
  return text(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

const companyNames = {
  'dr-woolrich': 'Dr. Woolrich',
  'zenda-cafe': 'Zenda Café',
  'especialidades-dentales': 'Especialidades Dentales',
  'green-chimp-express': 'Green Chimp Express · Chatbot + Landing'
};

const companyName = companyNames[row.company_key] || row.company_key || 'CRM';
const contactName = text(row.nombre_paciente, text(raw.nombre_completo, 'Contacto sin nombre'));
const phone = text(row.whatsapp_phone, text(raw.telefono, 'No registrado'));
const product = text(row.classification, text(raw.producto_interes, text(row.service, 'Sin producto')));
const business = text(raw.nombre_negocio, text(raw.tipo_negocio, 'No registrado'));
const assignedTo = text(row.assigned_to, 'Sin responsable');
const message = text(row.ultimo_mensaje_cliente, text(raw.ultimo_mensaje, 'Sin mensaje registrado'));
const reminderText = text(row.reminder_text, 'Dar seguimiento al contacto.');

const reminderDate = new Date(row.reminder_at);
const formattedDate = Number.isNaN(reminderDate.getTime())
  ? row.reminder_at
  : new Intl.DateTimeFormat('es-MX', {
      timeZone: 'America/Mexico_City',
      dateStyle: 'full',
      timeStyle: 'short'
    }).format(reminderDate);

const subject = `Seguimiento pendiente: ${contactName} · ${companyName}`;

const html = `
<div style="font-family:Arial,sans-serif;max-width:680px;margin:auto;color:#18202b">
  <div style="background:#17202a;color:white;padding:22px;border-radius:14px 14px 0 0">
    <div style="font-size:12px;letter-spacing:.08em;color:#8ad7ff">GREEN CHIMP CRM</div>
    <h2 style="margin:8px 0 0">Seguimiento programado desde el CRM</h2>
  </div>
  <div style="border:1px solid #dbe3ea;border-top:0;padding:22px;border-radius:0 0 14px 14px">
    <p style="font-size:16px"><strong>${escapeHtml(reminderText)}</strong></p>
    <table style="width:100%;border-collapse:collapse;font-size:14px">
      <tr><td style="padding:8px 0;color:#64748b">Fecha elegida en la página</td><td style="padding:8px 0"><strong>${escapeHtml(formattedDate)}</strong></td></tr>
      <tr><td style="padding:8px 0;color:#64748b">Empresa</td><td style="padding:8px 0">${escapeHtml(companyName)}</td></tr>
      <tr><td style="padding:8px 0;color:#64748b">Contacto</td><td style="padding:8px 0">${escapeHtml(contactName)}</td></tr>
      <tr><td style="padding:8px 0;color:#64748b">Teléfono</td><td style="padding:8px 0">${escapeHtml(phone)}</td></tr>
      <tr><td style="padding:8px 0;color:#64748b">Producto / servicio</td><td style="padding:8px 0">${escapeHtml(product)}</td></tr>
      <tr><td style="padding:8px 0;color:#64748b">Negocio</td><td style="padding:8px 0">${escapeHtml(business)}</td></tr>
      <tr><td style="padding:8px 0;color:#64748b">Responsable</td><td style="padding:8px 0">${escapeHtml(assignedTo)}</td></tr>
    </table>
    <div style="margin-top:18px;padding:14px;background:#f5f7fa;border-radius:10px">
      <div style="font-size:12px;color:#64748b;margin-bottom:6px">ÚLTIMO MENSAJE</div>
      <div>${escapeHtml(message)}</div>
    </div>
  </div>
</div>`;

return [{
  json: {
    ...row,
    lead_id: row.id,
    email_to: 'redfieldalex370@gmail.com',
    email_subject: subject,
    email_html: html
  }
}];
